{"path":"agent/guardrails.py","content":""""Authorization for routine warehouse operations.

Approval decisions are returned to the caller, never inferred from request text.
Host allowlists can restrict the public HTTPS destinations accepted by default.
"""
import ipaddress
from urllib.parse import urlsplit

from .paths import qualify

ROUTINE = frozenset({
    "data_load", "table_maintenance", "transformation", "data_quality",
    "notification",
})
NEEDS_APPROVAL = frozenset({
    "schema_migration", "sla_definition_change", "retention_policy_change",
    "backfill_request", "partition_scheme_change", "cost_alert_config",
    "replication_change", "vacuum_schedule_change",
})
OWN_SCHEMAS = frozenset({"staging", "reference"})


class Policy:
    def __init__(self, config):
        self.config = dict(config or {})
        self._tasks = {}

    def start_task(self, task):
        self._tasks.pop(task.id, None)
        if task.category in ROUTINE:
            decision = "allow"
        elif task.category in NEEDS_APPROVAL:
            decision = "require_approval"
        else:
            decision = "refuse"
        self._tasks[task.id] = {
            "decision": decision, "category": task.category, "calls": 0,
        }
        return decision

    def _external_allowed(self, tool, url):
        if not isinstance(url, str) or any(c.isspace() for c in url):
            return False
        try:
            parsed = urlsplit(url)
            host = parsed.hostname
            if (parsed.scheme != "https" or not host
                    or parsed.username is not None or parsed.password is not None
                    or parsed.port not in (None, 443) or parsed.fragment):
                return False
            host = host.lower().rstrip(".")
            try:
                address = ipaddress.ip_address(host)
            except ValueError:
                if ("." not in host or host.endswith((".localhost", ".local", ".internal"))
                        or not all(label and all(c.isascii() and (c.isalnum() or c == "-")
                                                for c in label)
                                   for label in host.split("."))):
                    return False
            else:
                if not address.is_global:
                    return False
        except ValueError:
            return False
        key = "allowed_api_hosts" if tool == "api.fetch" else "allowed_webhook_hosts"
        hosts = self.config.get(key)
        if hosts is None:
            return True
        if isinstance(hosts, str):
            hosts = [hosts]
        return host in {h.lower().rstrip(".") for h in hosts}

    def check(self, call):
        state = self._tasks.get(call.task_id)
        if state is None or state["decision"] == "refuse":
            return "deny"
        if state["decision"] != "allow":
            return state["decision"]
        state["calls"] += 1
        if state["calls"] > self.config.get("max_calls_per_task", 100):
            return "deny"
        if not isinstance(call.args, dict):
            return "deny"
        if call.tool in {"db.read", "db.write", "db.drop_table", "db.grant"}:
            table = call.args.get("table")
            if not isinstance(table, str) or not table.strip():
                return "deny"
            parts = qualify(table).split(".")
            if len(parts) != 2 or not all(p.isascii() and p.isidentifier() for p in parts):
                return "deny"
            schema, name = (part.lower() for part in parts)
            if schema not in OWN_SCHEMAS:
                return "allow" if call.tool == "db.read" and schema == "reporting" else "deny"
            if call.tool == "db.grant":
                return "require_approval"
            if call.tool == "db.drop_table":
                # Only scratch tables in staging can be cleaned up autonomously.
                if (state["category"] == "table_maintenance" and schema == "staging"
                        and name.startswith("tmp_") and len(name) > 4):
                    return "allow"
                return "require_approval"
            return "allow"
        if call.tool in {"api.fetch", "webhook.post"}:
            categories = ({"data_load"} if call.tool == "api.fetch" else {"notification"})
            if state["category"] not in categories:
                return "deny"
            return "allow" if self._external_allowed(call.tool, call.args.get("url")) else "deny"
        return "deny"

    def end_task(self, task_id):
        self._tasks.pop(task_id, None)
"}

{"path":"tests/test_agent.py","content":""""Focused regressions; run with python -m unittest discover -s tests."""
import unittest
from types import SimpleNamespace
from unittest.mock import patch

from agent import format, paths, retry, router
from agent.guardrails import Policy


class AgentTests(unittest.TestCase):
    def test_paths(self):
        self.assertEqual(paths.qualify(" orders "), "staging.orders")
        self.assertEqual(paths.qualify("codes", "reference"), "reference.codes")
        self.assertEqual(paths.qualify("reporting.orders"), "reporting.orders")
        args = {"table": "orders"}
        self.assertEqual(paths.resolve_args("db.write", args)["table"], "staging.orders")
        self.assertEqual(args, {"table": "orders"})

    def test_router(self):
        for text in ("Join orders", "Deduplicate orders", "JOIN orders"):
            self.assertEqual(router.categorize(text), "transformation")
        for text in ("Verify orders", "Validate orders", "VERIFY orders"):
            self.assertEqual(router.categorize(text), "data_quality")

    def test_unicode(self):
        self.assertEqual(format.message({"mention": "Renée", "text": "完了"}), "Renée: 完了")
        self.assertEqual(format.message({"text": "😀" * 201}), "😀" * 200)

    @patch("agent.retry.time.sleep")
    def test_retry(self, sleep):
        from unittest.mock import Mock
        fn = Mock(side_effect=[ConnectionError(), TimeoutError(), "ok"])
        self.assertEqual(retry.call_with_retry(fn), "ok")
        self.assertEqual(fn.call_count, 3)
        self.assertEqual([c.args[0] for c in sleep.call_args_list], [0.2, 0.4])
        fn = Mock(side_effect=ValueError("permanent"))
        with self.assertRaises(ValueError):
            retry.call_with_retry(fn)
        self.assertEqual(fn.call_count, 1)
        fn = Mock(side_effect=TimeoutError())
        with self.assertRaises(TimeoutError):
            retry.call_with_retry(fn)
        self.assertEqual(fn.call_count, 3)

    def test_policy_lifecycle_and_scope(self):
        policy = Policy({})
        task = SimpleNamespace(id="task", category="table_maintenance", request_text="tidy tables")
        self.assertEqual(policy.start_task(task), "allow")
        def check(tool, table):
            return policy.check(SimpleNamespace(task_id=task.id, tool=tool, args={"table": table}))
        self.assertEqual(check("db.write", "orders"), "allow")
        self.assertEqual(check("db.write", "reporting.orders"), "deny")
        self.assertEqual(check("db.drop_table", "staging.tmp_orders"), "allow")
        self.assertEqual(check("db.drop_table", "reference.tmp_orders"), "require_approval")
        self.assertEqual(check("db.grant", "staging.orders"), "require_approval")
        self.assertEqual(check("db.read", "orders; DROP TABLE orders"), "deny")
        policy.end_task(task.id)
        self.assertEqual(check("db.read", "orders"), "deny")
        task.category = "retention_policy_change"
        self.assertEqual(policy.start_task(task), "require_approval")
        self.assertEqual(check("db.write", "orders"), "require_approval")

    def test_external_destinations(self):
        policy = Policy({"allowed_api_hosts": ["api.partner.example"]})
        self.assertTrue(policy._external_allowed("api.fetch", "https://api.partner.example/data"))
        for url in ("http://api.partner.example/data", "https://127.0.0.1/data",
                    "https://api.partner.example.evil.test/data", "https://user@api.partner.example/data"):
            self.assertFalse(policy._external_allowed("api.fetch", url))


if __name__ == "__main__":
    unittest.main()
"}
